Problem:
A house painting company can transport their paint in large cans or small cans. Large cans can hold 6 litres of paint while small cans can hold 2 litres of paint. Since small cans can be used up quickly and thus, not dry up as easily, the company wants to have at most 30% of the cans be large cans. However, there has to be at least 20 large cans especially for the basic colours. If the company needs to transport at least 120 litres of paint, how many of each size of cans should be transported to minimize the total number of cans?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "large_cans",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "small_cans",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "large_cans",
     "coef": 1.0
    },
    {
     "var": "small_cans",
     "coef": 1.0
    }
   ]
  },
  "constraints": [
   {
    "name": "large_share_limit",
    "terms": [
     {
      "var": "large_cans",
      "coef": 0.7
     },
     {
      "var": "small_cans",
      "coef": -0.3
     }
    ],
    "sense": "<=",
    "rhs": 0.0
   },
   {
    "name": "minimum_large_cans",
    "terms": [
     {
      "var": "large_cans",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 20.0
   },
   {
    "name": "minimum_paint_litres",
    "terms": [
     {
      "var": "large_cans",
      "coef": 6.0
     },
     {
      "var": "small_cans",
      "coef": 2.0
     }
    ],
    "sense": ">=",
    "rhs": 120.0
   }
  ]
 },
 "facts": {
  "objective": 67.0,
  "values": {
   "large_cans": 20.0,
   "small_cans": 47.0
  },
  "binding": [
   "minimum_large_cans"
  ],
  "slack": {
   "large_share_limit": 0.1,
   "minimum_large_cans": 0.0,
   "minimum_paint_litres": 94.0
  },
